targets.query:
import "strings"

from(bucket: "home")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "can_frame" and r._field == "table_row")
  |> filter(fn: (r) => r.bus =~ /^${can_bus:regex}$/)
  |> map(fn: (r) => {
    cells = strings.split(v: r._value, t: "␟")
    return {r with seq: cells[0], dlc: cells[1], data: cells[2], dbc: cells[3], message: cells[4], decoded: cells[5]}
  })
  |> filter(fn: (r) => r.dbc =~ /^${dbc_file:regex}$/)
  |> group()
  |> sort(columns: ["_time"], desc: true)
  |> keep(columns: ["dbc", "message", "_time", "bus", "can_id", "data", "decoded", "dlc", "seq", "ext", "car"])
